from dataclasses import dataclass

from app.accounts.models import Account
from app.accounts.repository import AccountRepository
from app.security.hashing import hash_password


@dataclass
class AccountView:
    id: int
    name: str
    owner_email: str
    has_password: bool


def to_view(account: Account) -> AccountView:
    return AccountView(
        id=account.id,
        name=account.name,
        owner_email=account.owner_email,
        has_password=bool(account.password_hash),
    )


class AccountService:
    def __init__(self, repo: AccountRepository):
        self.repo = repo

    def create(self, name: str, owner_email: str, password: str) -> AccountView:
        account = self.repo.create(
            name=name,
            owner_email=owner_email,
            password_hash=hash_password(password),
        )
        return to_view(account)

    def rotate_password(self, account_id: int, new_password: str) -> AccountView:
        account = self.repo.get(account_id)
        account.password_hash = hash_password(new_password)
        self.repo.save(account)
        return to_view(account)

from datetime import datetime, timedelta

from app.billing.repository import InvoiceRepository

RETENTION_DAYS = 2190


class InvoiceService:
    def __init__(self, repo: InvoiceRepository):
        self.repo = repo

    def void_invoice(self, invoice_id: int, reason: str) -> bool:
        invoice = self.repo.get(invoice_id)
        if invoice is None:
            return False
        invoice.status = "void"
        invoice.void_reason = reason
        self.repo.save(invoice)
        return True

    def stale_drafts(self) -> list[int]:
        cutoff = datetime.utcnow() - timedelta(days=30)
        return [
            inv.id
            for inv in self.repo.find_drafts_before(cutoff)
        ]

    def purge_allowed(self, invoice) -> bool:
        age = datetime.utcnow() - invoice.created_at
        return age >= timedelta(days=RETENTION_DAYS)

