class PasswordResetService:
    def __init__(self, repo: CustomerRepository):
        self.repo = repo

    def request_reset(self, email: str) -> dict:
        customer = self.repo.find_by_email(email)
        if customer is None:
            return {"detail": "if the account exists, an email was sent"}

        token = secrets.token_urlsafe(32)
        self.repo.store_reset_token(customer.id, token)
        send_email(
            to=customer.email,
            subject="Reset your password",
            body=f"Use this link: https://app.example.com/reset?token={token}",
        )

        logger.info("reset token issued for customer %s: %s", customer.id, token)
        return {"detail": "if the account exists, an email was sent"}

