import graphene

from app.integrations.models import Integration


class IntegrationType(graphene.ObjectType):
    id = graphene.ID()
    provider = graphene.String()
    api_key_configured = graphene.Boolean()
    api_key_suffix = graphene.String()
    created_at = graphene.DateTime()

    def resolve_api_key_configured(self, info):
        return bool(self.api_key)

    def resolve_api_key_suffix(self, info):
        if not self.api_key:
            return None
        return self.api_key[-4:]


class Query(graphene.ObjectType):
    integration = graphene.Field(IntegrationType, id=graphene.ID(required=True))

    def resolve_integration(self, info, id):
        return Integration.objects.get(pk=id)


schema = graphene.Schema(query=Query)
